$ErrorActionPreference = 'Stop'
$path = 'src\editors\website\WebsiteEditor.tsx'
if (!(Test-Path $path)) { throw 'Run this from your Onyx Studio project root.' }
$expected = 'E76E8E21A4A5AF0884EA13B79D54E12C15F6CBBCA1081308E1C7196CE411A2EC'
if ((Get-FileHash -Algorithm SHA256 $path).Hash -ne $expected) {
  throw 'WebsiteEditor.tsx differs from the version used for this patch. Nothing changed. Send me your latest WebsiteEditor.tsx for a tailored patch.'
}
$backup = "$path.$(Get-Date -Format 'yyyyMMdd-HHmmss').bak"
Copy-Item $path $backup
try {
  [System.IO.File]::WriteAllBytes((Resolve-Path $path).Path, [Convert]::FromBase64String(''))
  npm run build
  if ($LASTEXITCODE -ne 0) { throw 'Build failed' }
  Write-Host 'Smart center guides installed and build passed!' -ForegroundColor Green
} catch {
  Copy-Item $backup $path -Force
  Write-Host 'Restored the previous WebsiteEditor.tsx.' -ForegroundColor Yellow
  throw
}
